import('./src/fold.ts').then(async ({fold}) => {
  const {readEvents} = await import('./src/log.ts');
  const g = fold(readEvents());
  const re = /moved (here )?from|was moved|moved to #|came from #|split (out )?from|originally (on|in|from)/i;
  for (const n of g.nodes.values()) {
    const t = [n.title, n.why, n.body, n.pending?.title, n.pending?.why].filter(Boolean).join('\n');
    if (re.test(t)) console.log(n.id, '|', (t.match(re)||[])[0]);
  }
})"

